mapper.insert:
INSERT INTO pet_treasure_hunt_records (
    record_id, account_id, spin_count, spin_source, paid_cost, bone_reward,
    extra_reward_text, bonus_spin_reward, symbols_json, detail_lines_json, created_at
) VALUES (
    #{recordId}, #{accountId}, #{spinCount}, #{spinSource}, #{paidCost}, #{boneReward},
    #{extraRewardText}, #{bonusSpinReward}, #{symbolsJson}, #{detailLinesJson}, #{createdAt}
)

mapper.select:
SELECT record_id, account_id, spin_count, spin_source, paid_cost, bone_reward,
       extra_reward_text, bonus_spin_reward, symbols_json, detail_lines_json, created_at
FROM pet_treasure_hunt_records
WHERE account_id = #{accountId}
ORDER BY created_at DESC, record_id DESC
LIMIT #{limit}

mapper.delete:
DELETE FROM pet_treasure_hunt_records
WHERE account_id = #{accountId}
  AND record_id NOT IN (
      SELECT record_id
      FROM pet_treasure_hunt_records
      WHERE account_id = #{accountId}
      ORDER BY created_at DESC, record_id DESC
      LIMIT #{limit}
  )
